#!/usr/bin/env node
// Tells IndexNow-enabled search engines (Bing, Yandex, Seznam, Naver...) that every
// sitemap URL changed. Bing's index also feeds Copilot and ChatGPT search.
// The URL list is read from the built sitemap (so docs pages are included and the list
// always matches what was deployed), and the key file /<key>.txt generated by the build
// must be live first.
//   node scripts/build.mjs && node scripts/indexnow.mjs
//   DIST=/tmp/out node scripts/indexnow.mjs      # a build made with DIST=/tmp/out
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { site } from "../src/site.mjs";

const dist = resolve(dirname(fileURLToPath(import.meta.url)), "..", process.env.DIST || "dist");
const sitemapFile = join(dist, "sitemap.xml");
if (!existsSync(sitemapFile)) {
  console.error("dist/sitemap.xml missing: run node scripts/build.mjs first");
  process.exit(1);
}
if (!site.indexNowKey) {
  console.error("site.indexNowKey is empty: nothing to submit");
  process.exit(1);
}
const decode = (s) => s.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">");
const urlList = [...readFileSync(sitemapFile, "utf8").matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => decode(m[1]));
if (!urlList.length) {
  console.error("sitemap.xml lists no URLs");
  process.exit(1);
}
// IndexNow rejects URLs from a host other than the one the key is published on, so a
// preview build (SITE_URL elsewhere) is refused here rather than by the API.
if (new URL(urlList[0]).host !== site.host) {
  console.error(`sitemap host ${new URL(urlList[0]).host} does not match SITE_URL host ${site.host}`);
  process.exit(1);
}

const res = await fetch("https://api.indexnow.org/indexnow", {
  method: "POST",
  headers: { "content-type": "application/json; charset=utf-8" },
  body: JSON.stringify({
    host: site.host,
    key: site.indexNowKey,
    keyLocation: `${site.url}/${site.indexNowKey}.txt`,
    urlList,
  }),
});
console.log(`IndexNow: HTTP ${res.status} for ${urlList.length} URLs`);
if (res.status >= 400) process.exit(1);
